        ToolReferenceEntry("g2_itpo_perm_dex", "POTIONS", "Spawn Elixir of Dexterity", "Permanently grants +3 dexterity. Learn the permanent-dexterity recipe before brewing it with Goblin Berries and King’s Sorrel. Sold by: Salandril. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_perm_dex", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_health_03", "POTIONS", "Spawn Elixir of Healing", "Restores 100 health. Use from inventory in a safe place. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_health_03", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_perm_health", "POTIONS", "Spawn Elixir of Life", "Permanently grants +20 maximum health. Sold by: Erol, Zuris. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_perm_health", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_perm_mana", "POTIONS", "Spawn Elixir of Spirit", "Permanently grants +5 maximum mana. This increases your capacity, rather than only refilling current mana. Sold by: Zuris. Harvested from: Skeleton Mage. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_perm_mana", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_perm_str", "POTIONS", "Spawn Elixir of Strength", "Permanently grants +3 strength. Learn the permanent-strength recipe before brewing it with Dragonroot and King’s Sorrel. Save permanent bonuses until after your planned training. Sold by: Zuris. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_perm_str", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_megadrink", "POTIONS", "Spawn Embarla Firgasto", "Permanently adds +15 to the higher of strength and dexterity; a tie selects strength. Brew on Irdorath from the recipe using 10 dragon eggs, one sulphur and one black pearl. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_megadrink", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_health_01", "POTIONS", "Spawn Essence of Healing", "Restores 50 health. Use from inventory in a safe place. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_health_01", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_perm_littlemana", "POTIONS", "Spawn Essence of Spirit", "Permanently grants +3 maximum mana. This rare Essence of Spirit is a capacity bonus, not an ordinary mana refill. Found at: Ruins of Jharkendar. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_perm_littlemana", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_health_02", "POTIONS", "Spawn Extract of Healing", "Restores 70 health. Use from inventory in a safe place. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_health_02", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_healrandolph_mis", "POTIONS", "Spawn Healing of Addiction", "Restores 50 health. This is Sagitta’s special medicine for Randolph; deliver it through the relevant quest dialogue. Found at: Sagittas Cave. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_healrandolph_mis", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_healobsession_mis", "POTIONS", "Spawn Healing of Possession", "Use for the possessed-character quest after obtaining the remedy through the fire-mage story. Sold by: Pyrokar. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_healobsession_mis", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_healhilda_mis", "POTIONS", "Spawn Healing of the Black Fever", "Sagitta’s medicine for Hilda. Deliver it through the farm quest dialogue. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_healhilda_mis", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_mana_03", "POTIONS", "Spawn Mana Elixir", "Restores 100 mana. Use from inventory in a safe place. Sold by: Fisk, Salandril. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_mana_03", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_mana_01", "POTIONS", "Spawn Mana Essence", "Restores 50 mana. Use from inventory in a safe place. Sold by: Cronos, Fisk, Gorax, Ignaz. Carried by: Miguel. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_mana_01", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_mana_02", "POTIONS", "Spawn Mana Extract", "Restores 75 mana. Use from inventory in a safe place. Sold by: Fisk, Miguel, Salandril, Scatty. Quest reward: The Lost Recipe. Carried by: Silvestro. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_mana_02", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_dragoneggdrinkneoras_mis", "POTIONS", "Spawn Potion of Dragon Egg Secretion", "Neoras’s dragon-egg potion permanently grants +3 strength and restores 100 health. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_dragoneggdrinkneoras_mis", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_addon_geist_02", "POTIONS", "Spawn Potion of Mental Alteration (safe)", "Fortuno’s memory-recovery potion. Follow Miguel’s recipe and the Fortuno quest; using a spawned potion alone does not repair the quest. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_addon_geist_02", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_addon_geist_01", "POTIONS", "Spawn Potion of Mental Alteration (unsafe)", "Unsafe memory potion for Fortuno. Drinking this variant removes 1,000 health and can kill the user. Complete the recipe’s poison-removal preparation before brewing the safe version. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_addon_geist_01", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_health_addon_04", "POTIONS", "Spawn Pure life energy", "Fully restores current health; it does not increase maximum health. Sold by: Fisk, Garett, Ignaz, Miguel. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_health_addon_04", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_mana_addon_04", "POTIONS", "Spawn Pure mana", "Fully restores current mana; it does not increase maximum mana. Sold by: Fisk, Ignaz, Sagitta, Zuris. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_mana_addon_04", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_speed", "POTIONS", "Spawn Speed Potion", "Grants sprinting for 5 minutes. Drink before a long journey or an escape. Sold by: Ignaz, Lutero. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_speed", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_potionofdeath_02_mis", "POTIONS", "Spawn The Tears of Innos", "A fire mage gains permanent +5 strength and +5 dexterity, full health/mana restoration and temporary sprinting. Drinking it as another guild kills the hero; paladins should use the Tears for their weapon-consecration story instead. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_potionofdeath_02_mis", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpo_potionofdeath_01_mis", "POTIONS", "Spawn The Tears of Innos", "Quest version of the Tears of Innos with initially unknown effects. Keep it until the story explains its use. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpo_potionofdeath_01_mis", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/lektvary/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpl_blueplant", "PLANTS AND ALCHEMY", "Spawn Blue Elder", "Restores 5 health • Restores 5 mana. Use from inventory in a safe place. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpl_blueplant", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/herbar/", codeCategory = CodeCategory.ITEMS),
        ToolReferenceEntry("g2_itpl_mushroom_01", "PLANTS AND ALCHEMY", "Spawn Dark Mushroom", "Restores 5 health. Every 50 Dark Mushrooms eaten grant +5 maximum mana in unmodified Night of the Raven. Sold by: Jora, Constantino. Carried by: Fortuno. Spawns a copy nearby. Pick it up to add it to inventory.", command = "insert itpl_mushroom_01", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/herbar/", codeCategory = CodeCategory.ITEMS),
