    private fun tips0(): List<ToolReferenceEntry> = listOf(
        ToolReferenceEntry("g2_tip_save", "STARTING OUT", "Keep several save slots", "Keep an earlier save before guild decisions, difficult fights and sailing away. Saving in one slot removes your fallback.", source = "https://www.worldofgothic.com/gothic2/?go=g2faq"),
        ToolReferenceEntry("g2_tip_build", "TRAINING", "Choose a main combat style", "Focus your early learning points on one weapon style and its supporting attribute. Spreading them across every skill delays a reliable fighting build.", source = "https://www.worldofgothic.com/gothic2/?go=g2faq"),
        ToolReferenceEntry("g2_tip_danger", "EXPLORATION", "Return to strong enemies later", "The countryside includes enemies much stronger than an early hero. Retreat and return with improved equipment and training.", source = "https://www.worldofgothic.com/gothic2/?go=g2faq"),
        ToolReferenceEntry("g2_tip_journal", "QUESTS", "Re-read the journal", "Read new journal entries after important conversations. They often clarify who to visit next or what item to bring.", source = "https://www.worldofgothic.com/gothic2/?go=g2faq"),
        ToolReferenceEntry("g2_tip_scrolls", "MAGIC", "Non-mages can use scrolls", "Scrolls provide access to spells without following the fire-mage path. They are consumable and still need mana.", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/magicke-svitky/"),
        ToolReferenceEntry("g2_tip_runes", "MAGIC", "Runes and scrolls work differently", "Runes are reusable; ordinary mage runes require the relevant magic circle. A spawned rune does not bypass that requirement.", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/magicke-runy/"),
        ToolReferenceEntry("g2_tip_tablets", "NIGHT OF THE RAVEN", "Learn the ancient languages", "Myxir teaches the language levels needed for magical tablets. A higher-level tablet requires the corresponding language knowledge.", source = "https://www.gothicz.net/gothic-2-noc-havrana/kamenne-tabulky/"),
        ToolReferenceEntry("g2_tip_bonuses", "NIGHT OF THE RAVEN", "Plan permanent bonuses", "In unmodified NotR, permanent attribute bonuses can push training into higher cost brackets. Consider training first, then consuming saved bonuses. Mods may handle this differently.", source = "https://www.gothicz.net/gothic-2-noc-havrana/kamenne-tabulky/"),
        ToolReferenceEntry("g2_tip_materials", "CRAFTING", "Keep rare recipe ingredients", "Do not sell rare plants or dragon materials blindly. Check future potion, rune and equipment recipes before clearing your inventory.", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/herbar/"),
        ToolReferenceEntry("g2_tip_harvest", "HUNTING", "Learn harvesting before the hunt", "Acquire the specific trophy skill before hunting for skins, plates, blood or scales. Different trophies require different knowledge.", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/trofeje/"),
        ToolReferenceEntry("g2_tip_ammo", "RANGED COMBAT", "Pack the correct ammunition", "Bows use arrows and crossbows use bolts. Expansion magic weapons have their own special ammunition.", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/kuse/"),
        ToolReferenceEntry("g2_tip_respawn", "NIGHT OF THE RAVEN", "Revisit Jharkendar in chapter 4", "After completing its story, Jharkendar receives additional monsters in chapter 4. A return visit can provide more combat experience.", source = "https://www.gothicz.net/gothic-2/tipy-a-triky/"),
        ToolReferenceEntry("g2_tip_gold_rules", "EDITION RULES", "These stats are for Gothic II Gold", "The reference uses Night of the Raven values. The original Gothic II has different requirements, damage and training costs. New Balance and other mods use their own rules.", source = "https://www.gothicz.net/gothic-2/predmety/jednorucni-zbrane/"),
        ToolReferenceEntry("g2_tip_merchant_chapters", "TRADING", "Merchant inventories change by chapter", "A listed merchant or location is an acquisition lead, not a promise that the item is available in chapter 1. Story, guild and chapter requirements still apply; some NPC-carried equipment cannot be obtained without fighting or stealing.", source = "https://www.gothicz.net/gothic-2/predmety/jednorucni-zbrane/"),
        ToolReferenceEntry("g2_tip_crossbows", "RANGED COMBAT", "Crossbows equip with strength", "In Gothic II Gold, bows require dexterity and crossbows require strength. Dexterity contributes to ranged damage for both. Weapon skill governs your effective chance of hitting.", source = "https://www.gothicz.net/gothic-2/predmety/kuse/"),
        ToolReferenceEntry("g2_tip_dex_melee", "MELEE COMBAT", "Dexterity swords still use melee strength", "Rapier, Master Sword and Betty require dexterity to equip. Their melee damage still benefits from strength; the equip requirement is not the damage attribute.", source = "https://www.gothicz.net/gothic-2/predmety/jednorucni-zbrane/"),
        ToolReferenceEntry("g2_tip_skill_bonus", "TRAINING", "Account for equipment skill bonuses", "Some weapons add weapon-skill percentage points while equipped. Unequip them when checking your unmodified training level; the bonus disappears when you change weapons.", source = "https://github.com/auronen/Gothic-2-localization/blob/master/Scripts/Content/Items/Einhand_EquipBonus.d"),
        ToolReferenceEntry("g2_tip_accessories", "EQUIPMENT", "Accessory bonuses require the item to stay equipped", "Rings, amulets and belts provide temporary equipment bonuses. They are distinct from permanent potion and tablet bonuses.", source = "https://github.com/auronen/Gothic-2-localization/blob/master/Scripts/Content/Items/IT_Ringe.d"),
        ToolReferenceEntry("g2_tip_sets", "EQUIPMENT", "Use matching Jharkendar artifact sets", "Each priest, healer and warrior set consists of two specific rings and one amulet. Wearing the whole matching set grants an extra bonus; two arbitrary rings do not count.", source = "https://github.com/auronen/Gothic-2-localization/blob/master/Scripts/Content/Items/IT_Addon_Amulette.d"),
        ToolReferenceEntry("g2_tip_belt_set", "EQUIPMENT", "Match a guild belt to its armor", "Leather, militia, mercenary, novice, fire-mage and minecrawler belts have a matching-armor bonus. The bonus disappears when you remove the matching armor or belt.", source = "https://github.com/auronen/Gothic-2-localization/blob/master/Scripts/Content/Items/IT_Addon_Belts.d"),
        ToolReferenceEntry("g2_tip_mushrooms", "PERMANENT BONUSES", "Keep Dark Mushrooms for mana", "Every 50 Dark Mushrooms eaten grant +5 maximum mana in unmodified Night of the Raven. Eating one also restores 5 health.", source = "https://github.com/auronen/Gothic-2-localization/blob/master/Scripts/Content/Items/IT_Plants.d"),
        ToolReferenceEntry("g2_tip_dragon_harvest", "HUNTING", "Learn dragon harvesting before killing dragons", "Learn the needed harvesting skills before the dragon hunt. Dragon scales are used for medium dragon-hunter armor, and dragon blood is used for high-tier ore weapons.", source = "https://www.gothicz.net/gothic-2/predmety/trofeje/"),
        ToolReferenceEntry("g2_tip_recharge_eye", "DRAGON HUNT", "Recharge the Eye between dragons", "Use a dragon heart and a laboratory water bottle at an alchemy bench to recharge the exhausted Eye of Innos. Wear the charged Eye for the next dragon conversation.", source = "https://github.com/auronen/Gothic-2-localization/blob/master/Scripts/Content/Items/MissionItems_3.d"),
        ToolReferenceEntry("g2_tip_bandit_clothes", "JHARKENDAR", "Wear bandit armor inside the bandit camp", "Get the bandit disguise through the pirate story and wear it before approaching the camp. Take it off around ordinary citizens and other friendly settlements.", source = "https://www.gothicz.net/gothic-2/predmety/zbroje/"),
        ToolReferenceEntry("g2_tip_npc_costumes", "MARVIN MODE", "NPC armor is separate from obtainable equipment", "Codes includes NPC costumes and unused variants. Items lists the armor the hero can normally obtain. Spawning an armor does not join its guild or complete an admission quest.", source = "https://www.gothicz.net/gothic-2/predmety/zbroje/"),
        ToolReferenceEntry("g2_tip_npc_copy", "MARVIN MODE", "An inserted NPC is a duplicate", "NPCs have separate world and chapter variants. Inserting one creates another character; it does not reliably recover a missing NPC, repair a quest or update chapter flags.", source = "https://www.gothicz.net/marvin/g2/insert-kody/npc/"),
    )

