        ToolReferenceEntry("g2_item_itpo_perm_health", "POTIONS", "Elixir of Life", "Permanently grants +20 maximum health. Sold by: Erol, Zuris.", source = "https://www.gothicz.net/gothic-2/predmety/lektvary/"),
